            try
            {
                resume = 0;
                if (!NativeMethods.EnumServicesStatusExW(
                        scm,
                        NativeMethods.SC_ENUM_PROCESS_INFO,
                        NativeMethods.SERVICE_WIN32,
                        NativeMethods.SERVICE_STATE_ALL,
                        buffer,
                        bytesNeeded,
                        out _,
                        out uint returned,
                        ref resume,
                        null))
                {
                    return map;
