                    var item = Marshal.PtrToStructure<NativeMethods.ENUM_SERVICE_STATUS_PROCESS>(ptr);
                    int pid = (int)item.ServiceStatusProcess.dwProcessId;
                    if (pid <= 0)
                        continue;

                    string name = Marshal.PtrToStringUni(item.lpServiceName) ?? string.Empty;
                    string display = Marshal.PtrToStringUni(item.lpDisplayName) ?? name;
                    if (string.IsNullOrWhiteSpace(name) && string.IsNullOrWhiteSpace(display))
                        continue;

                    if (!map.TryGetValue(pid, out var list))
                    {
                        list = new List<ServiceInfo>();
                        map[pid] = list;
