            }
            finally
            {
                Marshal.FreeHGlobal(buffer);
            }
        }
        catch
        {
            // Service enumeration is supplemental. A failure must never block process telemetry.
        }
        finally
        {
            NativeMethods.CloseServiceHandle(scm);
        }

        return map;
    }

    private static List<ProcessEntry> EnumerateProcesses()
