            var value = new FileMetadata(
                CleanMetadata(info.FileDescription),
                CleanMetadata(info.ProductName),
                CleanMetadata(info.CompanyName));
            _fileMetadataCache[path] = value;
            return value;
        }
        catch
        {
            var value = new FileMetadata(null, null, null);
            _fileMetadataCache[path] = value;
            return value;
        }
    }

